          "solution": "import java.util.Scanner;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.Locale;\n\npublic class Main {\n    public static double sumEssence(List<? extends Number> list) {\n        double sum = 0.0;\n        for (Number n : list) {\n            sum += n.doubleValue();\n        }\n        return sum;\n    }\n    \n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        List<Double> doubles = new ArrayList<>();\n        for (int i = 0; i < n; i++) {\n            doubles.add(sc.nextDouble());\n        }\n        double sum = sumEssence(doubles);\n        System.out.println(String.format(Locale.US, \"Total Essence: %.2f\", sum));\n    }\n}",
