    "glossary": [
      {
        "term": "Byte Stream",
        "definition": "An I/O stream (InputStream/OutputStream) that reads or writes raw binary 8-bit bytes without character encoding."
      },
      {
        "term": "Character Stream",
        "definition": "An I/O stream (Reader/Writer) that reads or writes 16-bit Unicode characters with character encoding translation."
      },
      {
        "term": "BufferedReader",
        "definition": "A character stream wrapper that buffers incoming data into a memory buffer to minimize underlying system calls."
      },
      {
        "term": "try-with-resources",
        "definition": "A Java control structure that guarantees all declared AutoCloseable resources are closed automatically upon block completion."
      },
      {
        "term": "AutoCloseable",
        "definition": "An interface providing a single close() method that qualifies implementing classes for automated management in try-with-resources."
      },
      {
        "term": "NIO.2",
        "definition": "The modern Java file I/O framework introduced in Java 7 centered on Path and Files."
      },
      {
        "term": "Path",
        "definition": "An immutable object representing the hierarchical location of a file or directory in a filesystem."
      },
      {
        "term": "Suppressed Exception",
        "definition": "An exception caught during resource closure that is attached to a primary exception via addSuppressed()."
      }
    ],
