    "glossary": [
      {
        "term": "Functional Interface",
        "definition": "An interface containing exactly one abstract method (Single Abstract Method or SAM), qualifying it as a target for lambda expressions."
      },
      {
        "term": "Lambda Expression",
        "definition": "An anonymous function that can be passed around as data and executed on demand."
      },
      {
        "term": "Method Reference",
        "definition": "A compact syntax (::) for referring to an existing method or constructor without calling it directly."
      },
      {
        "term": "Stream",
        "definition": "A sequence of elements supporting sequential and parallel aggregate operations across a lazy pipeline."
      },
      {
        "term": "flatMap",
        "definition": "An intermediate stream operation that maps each element to a stream and flattens the resulting streams into a single stream."
      },
      {
        "term": "IntStream",
        "definition": "A specialized primitive stream of int values that avoids the performance overhead of object boxing."
      },
      {
        "term": "Optional",
        "definition": "A container object that may or may not contain a non-null value, providing a type-safe alternative to null."
      },
      {
        "term": "Effectively Final",
        "definition": "A variable whose value is never changed after initialization, allowing it to be safely captured in lambdas."
      }
    ],
