    "glossary": [
      {
        "term": "Enum",
        "definition": "A specialized Java class type defining a fixed set of named constant instances with optional fields and methods."
      },
      {
        "term": "Record",
        "definition": "An immutable data-carrier class standardized in Java 16 where components automatically generate fields, accessors, equals, hashCode, and toString."
      },
      {
        "term": "Compact Constructor",
        "definition": "A concise constructor declaration in a record that validates or normalizes components without repeating field assignments."
      },
      {
        "term": "Sealed Class",
        "definition": "A class that explicitly restricts which subclasses can extend it using the permits keyword."
      },
      {
        "term": "Non-sealed",
        "definition": "A modifier used on a subclass of a sealed class to open it up for unrestricted extension by any outside class."
      },
      {
        "term": "Pattern Matching",
        "definition": "A language mechanism coupling a type test or structure deconstruction directly with the extraction of matched variables."
      },
      {
        "term": "Guard Clause (when)",
        "definition": "A boolean expression attached to a case label in a switch expression that must evaluate to true for the branch to match."
      },
      {
        "term": "Algebraic Data Type (ADT)",
        "definition": "A functional data modeling paradigm combining Sum Types (sealed interfaces) and Product Types (records) to prevent illegal states."
      }
    ],
