          "starterCode": "import java.util.Scanner;\n\npublic class Main {\n    // Implement isPotentiallyDangerousInput\n    \n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        // Test input validation\n        \n    }\n}",
